56	/// Different types of indirect branches encountered during disassembly.
57	enum class IndirectBranchType : char {
58	  UNKNOWN = 0,             /// Unable to determine type.
59	  POSSIBLE_TAIL_CALL,      /// Possibly a tail call.
60	  POSSIBLE_JUMP_TABLE,     /// Possibly a switch/jump table.
61	  POSSIBLE_PIC_JUMP_TABLE, /// Possibly a jump table for PIC.
62	  POSSIBLE_GOTO,           /// Possibly a gcc's computed goto.
63	  POSSIBLE_FIXED_BRANCH,   /// Possibly an indirect branch to a fixed location.
64	  POSSIBLE_PIC_FIXED_BRANCH, /// Possibly an indirect jump to a fixed entry in a
65	                             /// PIC jump table.
66	};
67	
68	/// Enum used for readability when describing different BTI instruction
69	/// variants. The variant is encoded as an immediate of the instruction in LLVM.
70	enum BTIKind {
71	  C, /// Accepting calls, and jumps using x16/x17.
72	  J, /// Accepting jumps.
73	  JC /// Accepting both.
74	};
75	
76	class MCPlusBuilder {
77	public:
78	  using AllocatorIdTy = uint16_t;
79	
80	  std::optional<int64_t> getAnnotationAtOpIndex(const MCInst &Inst,
81	                                                unsigned OpIndex) const {
82	    std::optional<unsigned> FirstAnnotationOp = getFirstAnnotationOpIndex(Inst);
83	    if (!FirstAnnotationOp)
84	      return std::nullopt;
85	
86	    if (*FirstAnnotationOp > OpIndex || Inst.getNumOperands() < OpIndex)
87	      return std::nullopt;
88	
89	    const auto *Op = Inst.begin() + OpIndex;
90	    const int64_t ImmValue = Op->getImm();
91	    return extractAnnotationIndex(ImmValue);
92	  }
93	
94	private:
95	  /// A struct that represents a single annotation allocator
96	  struct AnnotationAllocator {
97	    BumpPtrAllocator ValueAllocator;
98	    std::unordered_set<MCPlus::MCAnnotation *> AnnotationPool;
99	  };
100	
101	  /// A set of annotation allocators
102	  std::unordered_map<AllocatorIdTy, AnnotationAllocator> AnnotationAllocators;
103	
104	  /// A variable that is used to generate unique ids for annotation allocators
105	  AllocatorIdTy MaxAllocatorId = 0;
106	
107	  /// We encode Index and Value into a 64-bit immediate operand value.
108	  static int64_t encodeAnnotationImm(uint8_t Index, int64_t Value) {
109	    if (LLVM_UNLIKELY(Value != extractAnnotationValue(Value)))
110	      report_fatal_error("annotation value out of range");
111	
112	    Value &= 0xff'ffff'ffff'ffff;
113	    Value |= (int64_t)Index << 56;
114	
115	    return Value;
116	  }
117	
118	  /// Extract annotation index from immediate operand value.
119	  static uint8_t extractAnnotationIndex(int64_t ImmValue) {
120	    return ImmValue >> 56;
121	  }
122	
123	  /// Extract annotation value from immediate operand value.
124	  static int64_t extractAnnotationValue(int64_t ImmValue) {
125	    return SignExtend64<56>(ImmValue & 0xff'ffff'ffff'ffffULL);
126	  }
127	
128	  std::optional<unsigned> getFirstAnnotationOpIndex(const MCInst &Inst) const {
129	    const unsigned NumPrimeOperands = MCPlus::getNumPrimeOperands(Inst);
130	    if (Inst.getNumOperands() == NumPrimeOperands)
131	      return std::nullopt;
132	
133	    assert(Inst.getOperand(NumPrimeOperands).getInst() == nullptr &&
134	           "Empty instruction expected.");
135	
136	    return NumPrimeOperands + 1;
137	  }
138	
139	  MCInst::iterator getAnnotationInstOp(MCInst &Inst) const {
140	    for (MCInst::iterator Iter = Inst.begin(); Iter != Inst.end(); ++Iter) {
141	      if (MCPlus::isAnnotationSentinel(*Iter))
142	        return Iter;
143	    }
144	    return Inst.end();
145	  }
146	
147	  void removeAnnotations(MCInst &Inst) const {
148	    Inst.erase(getAnnotationInstOp(Inst), Inst.end());
149	  }
150	
151	  void setAnnotationOpValue(MCInst &Inst, unsigned Index, int64_t Value) const {
152	    const int64_t AnnotationValue = encodeAnnotationImm(Index, Value);
153	    const std::optional<unsigned> FirstAnnotationOp =
154	        getFirstAnnotationOpIndex(Inst);
155	    if (!FirstAnnotationOp) {
156	      Inst.addOperand(MCOperand::createInst(nullptr));
157	      Inst.addOperand(MCOperand::createImm(AnnotationValue));
158	      return;
159	    }
160	
161	    for (unsigned I = *FirstAnnotationOp; I < Inst.getNumOperands(); ++I) {
162	      const int64_t ImmValue = Inst.getOperand(I).getImm();
163	      if (extractAnnotationIndex(ImmValue) == Index) {
164	        Inst.getOperand(I).setImm(AnnotationValue);
165	        return;
166	      }
167	    }
168	
169	    Inst.addOperand(MCOperand::createImm(AnnotationValue));
170	  }
171	
172	  std::optional<int64_t> getAnnotationOpValue(const MCInst &Inst,
173	                                              unsigned Index) const {
174	    std::optional<unsigned> FirstAnnotationOp = getFirstAnnotationOpIndex(Inst);
175	    if (!FirstAnnotationOp)
176	      return std::nullopt;
177	
178	    for (unsigned I = *FirstAnnotationOp; I < Inst.getNumOperands(); ++I) {
179	      const int64_t ImmValue = Inst.getOperand(I).getImm();
180	      if (extractAnnotationIndex(ImmValue) == Index)
181	        return extractAnnotationValue(ImmValue);
182	    }
183	
184	    return std::nullopt;
185	  }
186	
187	protected:
188	  const MCInstrAnalysis *Analysis;
189	  const MCInstrInfo *Info;
190	  const MCRegisterInfo *RegInfo;
191	  const MCSubtargetInfo *STI;
192	
193	  /// Map annotation name into an annotation index.
194	  StringMap<uint64_t> AnnotationNameIndexMap;
195	
196	  /// Names of non-standard annotations.
197	  SmallVector<std::string, 8> AnnotationNames;
198	
199	  /// A mutex that is used to control parallel accesses to
200	  /// AnnotationNameIndexMap and AnnotationsNames.
201	  mutable llvm::sys::RWMutex AnnotationNameMutex;
202	
203	  /// Set TailCall annotation value to true. Clients of the target-specific
204	  /// MCPlusBuilder classes must use convert/lower/create* interfaces instead.
205	  void setTailCall(MCInst &Inst) const;
206	
207	public:
208	  /// Transfer annotations from \p SrcInst to \p DstInst.
209	  void moveAnnotations(MCInst &&SrcInst, MCInst &DstInst) const {
210	    MCInst::iterator AnnotationOp = getAnnotationInstOp(SrcInst);
211	    for (MCInst::iterator Iter = AnnotationOp; Iter != SrcInst.end(); ++Iter)
212	      DstInst.addOperand(*Iter);
213	
214	    SrcInst.erase(AnnotationOp, SrcInst.end());
215	  }
216	
217	  /// Return iterator range covering def operands.
218	  iterator_range<MCInst::iterator> defOperands(MCInst &Inst) const {
219	    return make_range(Inst.begin(),
220	                      Inst.begin() + Info->get(Inst.getOpcode()).getNumDefs());
221	  }
222	
223	  iterator_range<MCInst::const_iterator> defOperands(const MCInst &Inst) const {
224	    return make_range(Inst.begin(),
225	                      Inst.begin() + Info->get(Inst.getOpcode()).getNumDefs());
226	  }
227	
228	  /// Return iterator range covering prime use operands.
229	  iterator_range<MCInst::iterator> useOperands(MCInst &Inst) const {
230	    return make_range(Inst.begin() + Info->get(Inst.getOpcode()).getNumDefs(),
231	                      Inst.begin() + MCPlus::getNumPrimeOperands(Inst));
232	  }
233	
234	  iterator_range<MCInst::const_iterator> useOperands(const MCInst &Inst) const {
235	    return make_range(Inst.begin() + Info->get(Inst.getOpcode()).getNumDefs(),
236	                      Inst.begin() + MCPlus::getNumPrimeOperands(Inst));
237	  }
238	
239	public:
240	  class InstructionIterator {
241	  public:
242	    using iterator_category = std::bidirectional_iterator_tag;
243	    using value_type = MCInst;
244	    using difference_type = std::ptrdiff_t;
245	    using pointer = value_type *;
246	    using reference = value_type &;
247	
248	    class Impl {
249	    public:
250	      virtual Impl *Copy() const = 0;
251	      virtual void Next() = 0;
252	      virtual void Prev() = 0;
253	      virtual MCInst &Deref() = 0;
254	      virtual bool Compare(const Impl &Other) const = 0;
255	      virtual ~Impl() {}
256	    };
257	
258	    template <typename T> class SeqImpl : public Impl {
259	    public:
260	      virtual Impl *Copy() const override { return new SeqImpl(Itr); }
261	      virtual void Next() override { ++Itr; }
262	      virtual void Prev() override { --Itr; }
263	      virtual MCInst &Deref() override { return const_cast<MCInst &>(*Itr); }
264	      virtual bool Compare(const Impl &Other) const override {
265	        // assumes that Other is same underlying type
266	        return Itr == static_cast<const SeqImpl<T> &>(Other).Itr;
267	      }
268	      explicit SeqImpl(T &&Itr) : Itr(std::move(Itr)) {}
269	      explicit SeqImpl(const T &Itr) : Itr(Itr) {}
270	
271	    private:
272	      T Itr;
273	    };
274	
275	    template <typename T> class MapImpl : public Impl {
276	    public:
277	      virtual Impl *Copy() const override { return new MapImpl(Itr); }
278	      virtual void Next() override { ++Itr; }
279	      virtual void Prev() override { --Itr; }
280	      virtual MCInst &Deref() override {
281	        return const_cast<MCInst &>(Itr->second);
282	      }
283	      virtual bool Compare(const Impl &Other) const override {
284	        // assumes that Other is same underlying type
285	        return Itr == static_cast<const MapImpl<T> &>(Other).Itr;
286	      }
287	      explicit MapImpl(T &&Itr) : Itr(std::move(Itr)) {}
288	      explicit MapImpl(const T &Itr) : Itr(Itr) {}
289	
290	    private:
291	      T Itr;
292	    };
293	
294	    InstructionIterator &operator++() {
295	      Itr->Next();
296	      return *this;
297	    }
298	    InstructionIterator &operator--() {
299	      Itr->Prev();
300	      return *this;
301	    }
302	    InstructionIterator operator++(int) {
303	      std::unique_ptr<Impl> Tmp(Itr->Copy());
304	      Itr->Next();
305	      return InstructionIterator(std::move(Tmp));
306	    }
307	    InstructionIterator operator--(int) {
308	      std::unique_ptr<Impl> Tmp(Itr->Copy());
309	      Itr->Prev();
310	      return InstructionIterator(std::move(Tmp));
311	    }
312	    bool operator==(const InstructionIterator &Other) const {
313	      return Itr->Compare(*Other.Itr);
314	    }
315	    bool operator!=(const InstructionIterator &Other) const {
316	      return !Itr->Compare(*Other.Itr);
317	    }
318	    MCInst &operator*() { return Itr->Deref(); }
319	    MCInst *operator->() { return &Itr->Deref(); }
320	
321	    InstructionIterator &operator=(InstructionIterator &&Other) {
322	      Itr = std::move(Other.Itr);
323	      return *this;
324	    }
325	    InstructionIterator &operator=(const InstructionIterator &Other) {
326	      if (this != &Other)
327	        Itr.reset(Other.Itr->Copy());
328	      return *this;
329	    }
330	    InstructionIterator() {}
331	    InstructionIterator(const InstructionIterator &Other)
332	        : Itr(Other.Itr->Copy()) {}
333	    InstructionIterator(InstructionIterator &&Other)
334	        : Itr(std::move(Other.Itr)) {}
335	    explicit InstructionIterator(std::unique_ptr<Impl> Itr)
336	        : Itr(std::move(Itr)) {}
337	
338	    InstructionIterator(InstructionListType::iterator Itr)
339	        : Itr(new SeqImpl<InstructionListType::iterator>(Itr)) {}
340	
341	    template <typename T>
342	    InstructionIterator(T *Itr) : Itr(new SeqImpl<T *>(Itr)) {}
343	
344	    InstructionIterator(ArrayRef<MCInst>::iterator Itr)
345	        : Itr(new SeqImpl<ArrayRef<MCInst>::iterator>(Itr)) {}
346	
347	    InstructionIterator(MutableArrayRef<MCInst>::iterator Itr)
348	        : Itr(new SeqImpl<MutableArrayRef<MCInst>::iterator>(Itr)) {}
349	
350	    // TODO: it would be nice to templatize this on the key type.
351	    InstructionIterator(std::map<uint32_t, MCInst>::iterator Itr)
352	        : Itr(new MapImpl<std::map<uint32_t, MCInst>::iterator>(Itr)) {}
353	
354	  private:
355	    std::unique_ptr<Impl> Itr;
356	  };
357	
358	public:
359	  MCPlusBuilder(const MCInstrAnalysis *Analysis, const MCInstrInfo *Info,
360	                const MCRegisterInfo *RegInfo, const MCSubtargetInfo *STI)
361	      : Analysis(Analysis), Info(Info), RegInfo(RegInfo), STI(STI) {
362	    // Initialize the default annotation allocator with id 0
363	    AnnotationAllocators.emplace(0, AnnotationAllocator());
364	    MaxAllocatorId++;
365	    // Build alias map
366	    initAliases();
367	    initSizeMap();
368	  }
369	
370	  /// Create and return a target-specific MC symbolizer for the \p Function.
371	  /// When \p CreateNewSymbols is set, the symbolizer can create new symbols
372	  /// e.g. for jump table references.
373	  virtual std::unique_ptr<MCSymbolizer>
374	  createTargetSymbolizer(BinaryFunction &Function,
375	                         bool CreateNewSymbols = true) const {
376	    return nullptr;
377	  }
378	
379	  /// Initialize a new annotation allocator and return its id
380	  AllocatorIdTy initializeNewAnnotationAllocator() {
381	    AnnotationAllocators.emplace(MaxAllocatorId, AnnotationAllocator());
382	    return MaxAllocatorId++;
383	  }
384	
385	  /// Return the annotation allocator of a given id
386	  AnnotationAllocator &getAnnotationAllocator(AllocatorIdTy AllocatorId) {
387	    assert(AnnotationAllocators.count(AllocatorId) &&
388	           "allocator not initialized");
389	    return AnnotationAllocators.find(AllocatorId)->second;
390	  }
391	
392	  // Check if an annotation allocator with the given id exists
393	  bool checkAllocatorExists(AllocatorIdTy AllocatorId) {
394	    return AnnotationAllocators.count(AllocatorId);
395	  }
396	
397	  /// Free the values allocator within the annotation allocator
398	  void freeValuesAllocator(AllocatorIdTy AllocatorId) {
399	    AnnotationAllocator &Allocator = getAnnotationAllocator(AllocatorId);
400	    for (MCPlus::MCAnnotation *Annotation : Allocator.AnnotationPool)
401	      Annotation->~MCAnnotation();
402	
403	    Allocator.AnnotationPool.clear();
404	    Allocator.ValueAllocator.Reset();
405	  }
406	
407	  virtual ~MCPlusBuilder() { freeAnnotations(); }
408	
409	  /// Free all memory allocated for annotations
410	  void freeAnnotations() {
411	    for (auto &Element : AnnotationAllocators) {
412	      AnnotationAllocator &Allocator = Element.second;
413	      for (MCPlus::MCAnnotation *Annotation : Allocator.AnnotationPool)
414	        Annotation->~MCAnnotation();
415	
416	      Allocator.AnnotationPool.clear();
417	      Allocator.ValueAllocator.Reset();
418	    }
419	  }
420	
421	  using CompFuncTy = std::function<bool(const MCSymbol *, const MCSymbol *)>;
422	
423	  bool equals(const MCInst &A, const MCInst &B, CompFuncTy Comp) const;
424	
425	  bool equals(const MCOperand &A, const MCOperand &B, CompFuncTy Comp) const;
426	
427	  bool equals(const MCExpr &A, const MCExpr &B, CompFuncTy Comp) const;
428	
429	  virtual bool equals(const MCSpecifierExpr &A, const MCSpecifierExpr &B,
430	                      CompFuncTy Comp) const;
431	
432	  virtual bool isBranch(const MCInst &Inst) const {
433	    return Analysis->isBranch(Inst);
434	  }
435	
436	  virtual bool isConditionalBranch(const MCInst &Inst) const {
437	    return Analysis->isConditionalBranch(Inst);
438	  }
439	
440	  /// Returns true if Inst is a conditional move instruction
441	  virtual bool isConditionalMove(const MCInst &Inst) const {
442	    llvm_unreachable("not implemented");
443	    return false;
444	  }
445	
446	  virtual bool isUnconditionalBranch(const MCInst &Inst) const {
447	    return Analysis->isUnconditionalBranch(Inst) && !isTailCall(Inst);
448	  }
449	
450	  virtual bool isIndirectBranch(const MCInst &Inst) const {
451	    return Analysis->isIndirectBranch(Inst);
452	  }
453	
454	  /// Returns true if the instruction unconditionally transfers the control to
455	  /// another program point, interrupting sequential code execution, e.g. by a
456	  /// call, return, or unconditional jump. This explicitly leaves out
457	  /// conditional branches as they may not be taken, but does allow transferring
458	  /// the control to the next instruction (zero-displacement jump/call).
459	  bool isUnconditionalControlTransfer(const MCInst &Inst) const {
460	    const MCInstrDesc &Desc = Info->get(Inst.getOpcode());
461	    // barrier captures returns and unconditional branches
462	    return Desc.isBarrier() || Desc.isCall();
463	  }
464	
465	  /// Returns true if the instruction is memory indirect call or jump
466	  virtual bool isBranchOnMem(const MCInst &Inst) const {
467	    llvm_unreachable("not implemented");
468	    return false;
469	  }
470	
471	  /// Returns true if the instruction is register indirect call or jump
472	  virtual bool isBranchOnReg(const MCInst &Inst) const {
473	    llvm_unreachable("not implemented");
474	    return false;
475	  }
476	
477	  /// Check whether this conditional branch can be reversed
478	  virtual bool isReversibleBranch(const MCInst &Inst) const {
479	    assert(!isUnsupportedInstruction(Inst) && isConditionalBranch(Inst) &&
