922	  /// Interface and basic functionality of a MCInstMatcher. The idea is to make
923	  /// it easy to match one or more MCInsts against a tree-like pattern and
924	  /// extract the fragment operands. Example:
925	  ///
926	  ///   auto IndJmpMatcher =
927	  ///       matchIndJmp(matchAdd(matchAnyOperand(), matchAnyOperand()));
928	  ///   if (!IndJmpMatcher->match(...))
929	  ///     return false;
930	  ///
931	  /// This matches an indirect jump whose target register is defined by an
932	  /// add to form the target address. Matchers should also allow extraction
933	  /// of operands, for example:
934	  ///
935	  ///   uint64_t Scale;
936	  ///   auto IndJmpMatcher = BC.MIA->matchIndJmp(
937	  ///       BC.MIA->matchAnyOperand(), BC.MIA->matchImm(Scale),
938	  ///       BC.MIA->matchReg(), BC.MIA->matchAnyOperand());
939	  ///   if (!IndJmpMatcher->match(...))
940	  ///     return false;
941	  ///
942	  /// Here we are interesting in extracting the scale immediate in an indirect
943	  /// jump fragment.
944	  ///
945	  struct MCInstMatcher {
946	    MutableArrayRef<MCInst> InstrWindow;
947	    MutableArrayRef<MCInst>::iterator CurInst;
948	    virtual ~MCInstMatcher() {}
949	
950	    /// Returns true if the pattern is matched. Needs MCRegisterInfo and
951	    /// MCInstrAnalysis for analysis. InstrWindow contains an array
952	    /// where the last instruction is always the instruction to start matching
953	    /// against a fragment, potentially matching more instructions before it.
954	    /// If OpNum is greater than 0, we will not match against the last
955	    /// instruction itself but against an operand of the last instruction given
956	    /// by the index OpNum. If this operand is a register, we will immediately
957	    /// look for a previous instruction defining this register and match against
958	    /// it instead. This parent member function contains common bookkeeping
959	    /// required to implement this behavior.
960	    virtual bool match(const MCRegisterInfo &MRI, MCPlusBuilder &MIA,
961	                       MutableArrayRef<MCInst> InInstrWindow, int OpNum) {
962	      InstrWindow = InInstrWindow;
963	      CurInst = InstrWindow.end();
964	
965	      if (!next())
966	        return false;
967	
968	      if (OpNum < 0)
969	        return true;
970	
971	      if (static_cast<unsigned int>(OpNum) >=
972	          MCPlus::getNumPrimeOperands(*CurInst))
973	        return false;
974	
975	      const MCOperand &Op = CurInst->getOperand(OpNum);
976	      if (!Op.isReg())
977	        return true;
978	
979	      MCPhysReg Reg = Op.getReg();
980	      while (next()) {
981	        const MCInstrDesc &InstrDesc = MIA.Info->get(CurInst->getOpcode());
982	        if (InstrDesc.hasDefOfPhysReg(*CurInst, Reg, MRI)) {
983	          InstrWindow = InstrWindow.slice(0, CurInst - InstrWindow.begin() + 1);
984	          return true;
985	        }
986	      }
987	      return false;
988	    }
989	
990	    /// If successfully matched, calling this function will add an annotation
991	    /// to all instructions that were matched. This is used to easily tag
992	    /// instructions for deletion and implement match-and-replace operations.
993	    virtual void annotate(MCPlusBuilder &MIA, StringRef Annotation) {}
994	
995	    /// Moves internal instruction iterator to the next instruction, walking
996	    /// backwards for pattern matching (effectively the previous instruction in
997	    /// regular order).
998	    bool next() {
999	      if (CurInst == InstrWindow.begin())
1000	        return false;
1001	      --CurInst;
1002	      return true;
1003	    }
1004	  };
