1006	  /// Matches any operand
1007	  struct AnyOperandMatcher : MCInstMatcher {
1008	    MCOperand &Op;
1009	    AnyOperandMatcher(MCOperand &Op) : Op(Op) {}
1010	
1011	    bool match(const MCRegisterInfo &MRI, MCPlusBuilder &MIA,
1012	               MutableArrayRef<MCInst> InInstrWindow, int OpNum) override {
1013	      auto I = InInstrWindow.end();
1014	      if (I == InInstrWindow.begin())
1015	        return false;
1016	      --I;
1017	      if (OpNum < 0 ||
1018	          static_cast<unsigned int>(OpNum) >= MCPlus::getNumPrimeOperands(*I))
1019	        return false;
1020	      Op = I->getOperand(OpNum);
1021	      return true;
1022	    }
1023	  };
