1537	    if (auto *SymExpr = dyn_cast<MCSymbolRefExpr>(Expr)) {
1538	      return std::make_pair(&SymExpr->getSymbol(), 0);
1539	    } else if (auto *BinExpr = dyn_cast<MCBinaryExpr>(Expr)) {
1540	      const auto *SymExpr = dyn_cast<MCSymbolRefExpr>(BinExpr->getLHS());
1541	      const auto *ConstExpr = dyn_cast<MCConstantExpr>(BinExpr->getRHS());
1542	      if (BinExpr->getOpcode() == MCBinaryExpr::Add && SymExpr && ConstExpr)
1543	        return std::make_pair(&SymExpr->getSymbol(), ConstExpr->getValue());
1544	    }
1545	    return std::make_pair(nullptr, 0);
1546	  }
