2200	
2201	  /// Extract a symbol and an addend out of the fixup value expression.
2202	  ///
2203	  /// Only the following limited expression types are supported:
2204	  ///   Symbol + Addend
2205	  ///   Symbol + Constant + Addend
2206	  ///   Const + Addend
2207	  ///   Symbol
2208	  std::pair<MCSymbol *, uint64_t> extractFixupExpr(const MCFixup &Fixup) const {
2209	    uint64_t Addend = 0;
2210	    MCSymbol *Symbol = nullptr;
2211	    const MCExpr *ValueExpr = Fixup.getValue();
2212	    if (ValueExpr->getKind() == MCExpr::Binary) {
2213	      const auto *BinaryExpr = cast<MCBinaryExpr>(ValueExpr);
2214	      assert(BinaryExpr->getOpcode() == MCBinaryExpr::Add &&
2215	             "unexpected binary expression");
2216	      const MCExpr *LHS = BinaryExpr->getLHS();
2217	      if (LHS->getKind() == MCExpr::Constant) {
2218	        Addend = cast<MCConstantExpr>(LHS)->getValue();
2219	      } else if (LHS->getKind() == MCExpr::Binary) {
2220	        const auto *LHSBinaryExpr = cast<MCBinaryExpr>(LHS);
2221	        assert(LHSBinaryExpr->getOpcode() == MCBinaryExpr::Add &&
2222	               "unexpected binary expression");
2223	        const MCExpr *LLHS = LHSBinaryExpr->getLHS();
2224	        assert(LLHS->getKind() == MCExpr::SymbolRef && "unexpected LLHS");
2225	        Symbol = const_cast<MCSymbol *>(this->getTargetSymbol(LLHS));
2226	        const MCExpr *RLHS = LHSBinaryExpr->getRHS();
2227	        assert(RLHS->getKind() == MCExpr::Constant && "unexpected RLHS");
2228	        Addend = cast<MCConstantExpr>(RLHS)->getValue();
2229	      } else {
2230	        assert(LHS->getKind() == MCExpr::SymbolRef && "unexpected LHS");
2231	        Symbol = const_cast<MCSymbol *>(this->getTargetSymbol(LHS));
2232	      }
2233	      const MCExpr *RHS = BinaryExpr->getRHS();
2234	      assert(RHS->getKind() == MCExpr::Constant && "unexpected RHS");
2235	      Addend += cast<MCConstantExpr>(RHS)->getValue();
2236	    } else {
2237	      assert(ValueExpr->getKind() == MCExpr::SymbolRef && "unexpected value");
2238	      Symbol = const_cast<MCSymbol *>(this->getTargetSymbol(ValueExpr));
2239	    }
2240	    return std::make_pair(Symbol, Addend);
2241	  }
